import { after } from 'next/server';
import { revalidateTag } from 'next/cache';
import { redirect } from 'next/navigation';
import { getProducts, type Product } from '@/lib/products';

const STATUS_LABELS: Record<Product['status'], string> = {
  active: 'Active',
  low_stock: 'Low stock',
  out_of_stock: 'Out of stock',
};

const STATUS_COLORS: Record<Product['status'], string> = {
  active: '#16a34a',
  low_stock: '#d97706',
  out_of_stock: '#dc2626',
};

export default async function AdminCatalogPage({
  searchParams,
}: {
  searchParams: Promise<{ synced?: string }>;
}) {
  const { synced } = await searchParams;
  const products = await getProducts();

  async function syncCatalog() {
    'use server';

    // Schedule the expensive ERP/PIM sync to run in the background after the
    // response is sent so the admin isn't blocked waiting for it to finish.
    after(async () => {
      // In production this would call the upstream ERP/PIM API and write
      // results back to the database. We simulate that work with a delay.
      await new Promise((resolve) => setTimeout(resolve, 3000));

      // Invalidate all cache entries tagged "products" so the next request
      // to any view that depends on this tag picks up fresh data.
      revalidateTag('products');
    });

    redirect('/admin/catalog?synced=1');
  }

  return (
    <main style={{ fontFamily: 'system-ui, sans-serif', maxWidth: 900, margin: '0 auto', padding: '2rem 1rem' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '1.5rem' }}>
        <div>
          <h1 style={{ margin: 0, fontSize: '1.5rem', fontWeight: 700 }}>Product Catalog</h1>
          <p style={{ margin: '0.25rem 0 0', color: '#6b7280', fontSize: '0.875rem' }}>
            {products.length} products
          </p>
        </div>

        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              background: '#2563eb',
              color: '#fff',
              border: 'none',
              borderRadius: '0.375rem',
              fontWeight: 600,
              fontSize: '0.875rem',
              cursor: 'pointer',
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      {synced && (
        <div
          role="status"
          style={{
            marginBottom: '1.25rem',
            padding: '0.75rem 1rem',
            background: '#eff6ff',
            border: '1px solid #bfdbfe',
            borderRadius: '0.375rem',
            color: '#1d4ed8',
            fontSize: '0.875rem',
          }}
        >
          Sync triggered — catalog data will refresh in the background shortly.
        </div>
      )}

      <div style={{ overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.875rem' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid #e5e7eb', textAlign: 'left' }}>
              <th style={thStyle}>SKU</th>
              <th style={thStyle}>Name</th>
              <th style={{ ...thStyle, textAlign: 'right' }}>Price</th>
              <th style={{ ...thStyle, textAlign: 'right' }}>Stock</th>
              <th style={thStyle}>Status</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product) => (
              <tr key={product.id} style={{ borderBottom: '1px solid #f3f4f6' }}>
                <td style={{ ...tdStyle, fontFamily: 'monospace', color: '#6b7280' }}>{product.sku}</td>
                <td style={{ ...tdStyle, fontWeight: 500 }}>{product.name}</td>
                <td style={{ ...tdStyle, textAlign: 'right' }}>${product.price.toLocaleString()}</td>
                <td style={{ ...tdStyle, textAlign: 'right' }}>{product.stock}</td>
                <td style={tdStyle}>
                  <span
                    style={{
                      display: 'inline-block',
                      padding: '0.125rem 0.5rem',
                      borderRadius: '9999px',
                      fontSize: '0.75rem',
                      fontWeight: 600,
                      color: STATUS_COLORS[product.status],
                      background: STATUS_COLORS[product.status] + '18',
                    }}
                  >
                    {STATUS_LABELS[product.status]}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </main>
  );
}

const thStyle: React.CSSProperties = {
  padding: '0.625rem 0.75rem',
  fontWeight: 600,
  color: '#374151',
};

const tdStyle: React.CSSProperties = {
  padding: '0.75rem',
  color: '#111827',
};

